  const positions = await cameraService.getPositions();
  res.json(positions);
});

app.get('/camera/orientations', async (req, res) => {
  const orientations = await cameraService.getOrientations();
  res.json(orientations);
});

app.get('/camera/animations', async (req, res) => {
  const animations = await cameraService.getAnimations();
  res.json(animations);
});

