  await cameraService.playAnimation(req.body.animationId);
  res.json({ message: 'Animation played' });
});

app.post('/camera/pause', async (req, res) => {
  await cameraService.pauseAnimation(req.body.animationId);
  res.json({ message: 'Animation paused' });
});

app.post('/camera/stop', async (req, res) => {
  await cameraService.stopAnimation(req.body.animationId);
  res.json({ message: 'Animation stopped' });
});

app.post('/camera/update', async (req, res) => {
  await cameraService.updatePosition(req.body.position);
  await cameraService.updateOrientation(req.body.orientation);
  res.json({ message: 'Position and orientation updated' });
});

app.listen(3000, () => {
  console.log('Camera API started on port 3000');
});
```
