import { Vector3 } from 'three';

class Camera {
  private position: Vector3;
  private target: Vector3;
  private up: Vector3;
  private distance: number;
  private fov: number;

  constructor(position: Vector3, target: Vector3, up: Vector3, distance: number, fov: number) {
    this.position = position;
    this.target = target;
    this.up = up;
    this.distance = distance;
    this.fov = fov;
  }

  // Getters and setters
