module ldpc_encoder(
    input wire clock,
    input wire reset,
    input wire data_in,
    output wire data_out,
    output wire error
);

reg [7:0] data_reg;
reg [7:0] parity_reg;
reg [7:0] check_reg;

always @(posedge clock or posedge reset)
begin
    if (reset)
    begin
        data_reg <= 8'b00000000;
        parity_reg <= 8'b00000000;
        check_reg <= 8'b00000000;
    end
    else
    begin
        data_reg <= data_in;
        parity_reg <= parity_gen(data_reg);
        check_reg <= check_gen(data_reg, parity_reg);
    end
end

always @*
begin
    if (check_reg != 8'b00000000)
    begin
        error <= 1'b1;
    end
    else
    begin
        error <= 1'b0;
    end
end

endmodule

