func parseGoStruct(content []byte, structName string) (*reflect.Struct, error) {
	// Parse the Go source file for the struct definition
	packageName := "your_package_name"
	structType := reflect.TypeOf(&structName)
	structValue := reflect.ValueOf(&structName)

	// Check if the struct is exported and has a valid name
	if !structType.Exported() || !strings.HasPrefix(structName, packageName) {
		return nil, fmt.Errorf("struct is not exported or has an invalid name")
	}

	// Get the struct's fields and their types
