	fieldTypes := make([]reflect.Type, len(fields))
	for i, field := range fields {
		fieldTypes[i] = field.Type
	}

	// Return the struct definition
	return &reflect.Struct{Name: structName, Fields: fields, FieldTypes: fieldTypes}, nil
}

func generateAVROSchema(structDef *reflect.Struct) ([]byte, error) {
	// Generate the AVRO schema for the struct
	schemaBuilder := schema.Builder{}
	schemaBuilder.SetName(structDef.Name)

	// Iterate over the struct's fields and generate the schema for each field
	for i, field := range structDef.Fields {
		fieldType := field.Type
		fieldName := field.Name

		// Generate the schema for the field
		fieldSchema, err := generateAVROSchemaField(fieldType, fieldName)
		if err != nil {
			return nil, err
		}

		// Add the field schema to the overall schema
		schemaBuilder.AddField(fieldSchema)
	}

	// Generate the final AVRO schema
	schema, err := schemaBuilder.Build()
	if err != nil {
		return nil, err
	}

	// Convert the AVRO schema to a JSON format
	jsonSchema, err := schema.ToJSON()
	if err != nil {
		return nil, err
	}

	// Return the JSON schema
	return jsonSchema, nil
