func generateAVROSchemaField(fieldType reflect.Type, fieldName string) (*schema.Field, error) {
	// Generate the AVRO schema for the field
	schemaBuilder := schema.Builder{}
	schemaBuilder.SetName(fieldName)

	// Determine the AVRO schema type based on the Go type
	switch fieldType.Kind() {
	case reflect.String:
		schemaBuilder.SetType("string")
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		schemaBuilder.SetType("int")
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		schemaBuilder.SetType("long")
	case reflect.Float32, reflect.Float64:
		schemaBuilder.SetType("double")
	case reflect.Bool:
		schemaBuilder.SetType("boolean")
	case reflect.Interface:
		// Handle interface types
		schemaBuilder.SetType("record")
		schemaBuilder.AddField(generateAVROSchemaField(fieldType.Elem().Type, fieldName))
	case reflect.Slice:
		// Handle slice types
		schemaBuilder.SetType("array")
		schemaBuilder.AddField(generateAVROSchemaField(fieldType.Elem().Type, fieldName))
	default:
		return nil, fmt.Errorf("unsupported type: %v", fieldType.Kind())
	}

	// Generate the final AVRO schema
	fieldSchema, err := schemaBuilder.Build()
	if err != nil {
		return nil, err
	}

	// Return the AVRO schema
	return fieldSchema, nil
